  useEffect(()=>{if(view!=='community')return;const request=++boardRequest.current;const timer=setTimeout(()=>{setBoardBusy(true);const params=new URLSearchParams({q:postQuery,...(postFilter==='My posts'?{mine:'1'}:postFilter!=='All'?{type:postFilter}:{})});api(`posts?${params}`).then(data=>{if(request===boardRequest.current){setBoardPosts(data.posts);setBoardMore(data.more);setCommunityError('');}}).catch(error=>{if(request===boardRequest.current)setCommunityError(error.message);}).finally(()=>{if(request===boardRequest.current)setBoardBusy(false);});},180);return()=>{clearTimeout(timer);};},[view,postFilter,postQuery,posts]);
